async function main() {
    const fs = await import("fs");
    const path = await import("path");
    const fixturesDir = "/repo/packages/cli/openapi-parser/src/__test__/fixtures";
    const outDir = process.argv[2] ?? "/tmp/opencode/ir-dump";
    fs.mkdirSync(outDir, { recursive: true });
