        const openApiFile = files.find((f) => /\.(yml|yaml|json)$/.test(f) && !f.toLowerCase().includes("override"));
        if (openApiFile == null) { console.error(`${name}: no spec file`); failed++; continue; }
        try {
            const ir = await parse({ absolutePathToAsyncAPI: undefined, absolutePathToOpenAPI: AbsoluteFilePath.of(path.join(fixturesDir, name, openApiFile)), absolutePathToOpenAPIOverrides: undefined, taskContext: { logger, failAndThrow: (msg: string) => { throw new Error(msg); } } as any });
            fs.writeFileSync(path.join(outDir, `${name}.json`), JSON.stringify(ir, null, 2));
        } catch (e) { failed++; console.error(`${name}: CRASH ${(e as Error).message}`); }
