import { AbsoluteFilePath } from "@fern-api/fs-utils";
import { createMockTaskContext } from "@fern-api/task-context";
import { CONSOLE_LOGGER } from "@fern-api/logger";
import { parse } from "@fern-api/openapi-parser";
import { writeFileSync, mkdirSync } from "fs";
import { basename } from "path";
import { convert } from "./src/convert";

async function main() {
    const targets = ["/tmp/opencode/conflict/spec.yaml"];
    const outDir = "/tmp/opencode/fern-out-final";
    mkdirSync(outDir, { recursive: true });
    const taskContext = createMockTaskContext({ logger: CONSOLE_LOGGER });
    let failed = 0;
    for (const file of targets) {
        try {
            const ir = await parse({
                absolutePathToAsyncAPI: undefined,
                absolutePathToOpenAPI: AbsoluteFilePath.of(file),
                absolutePathToOpenAPIOverrides: undefined,
                taskContext
            });
            const fern = convert({ openApiIr: ir, taskContext });
            const key = basename(file).replace(/\.(yml|yaml|json)$/, "");
            writeFileSync(`${outDir}/${key}.json`, JSON.stringify(fern, null, 2));
            console.log(basename(file), "OK");
        } catch (e) {
            failed++;
            console.log(basename(file), "CRASH:", (e as Error).message.replace(/\n/g, " ").slice(0, 150));
        }
    }
    console.log("done failed=" + failed);
}
main();

