import { AbsoluteFilePath, join, RelativeFilePath } from "@fern-api/fs-utils";
import { parse } from "@fern-api/openapi-parser";
import { createWriteStream } from "fs";
import { convert } from "./src/convert";

const taskContext = {
    logger: console,
    failAndThrow: (message: string): never => {
        throw new Error(message);
    }
} as any;

async function main() {
    const specDir = "/tmp/opencode/conflict";
    const openApiPath = join(AbsoluteFilePath.of(specDir), RelativeFilePath.of("spec.yaml"));
    const out = createWriteStream("/tmp/opencode/conflict/result.json");
    const ir = await parse({
        absolutePathToAsyncAPI: undefined,
        absolutePathToOpenAPI: openApiPath,
        absolutePathToOpenAPIOverrides: undefined,
        taskContext
    });

    out.write("=== SCHEMAS ===\n");
    for (const [id, schema] of Object.entries(ir.schemas)) {
        const anySchema = schema as any;
        out.write(
            `${id}: type=${anySchema.type} generatedName=${JSON.stringify(anySchema.generatedName)} nameOverride=${JSON.stringify(anySchema.nameOverride)}\n`
        );
    }
    out.write("=== ERRORS ===\n");
    for (const [status, err] of Object.entries(ir.errors)) {
        const anyErr = err as any;
        out.write(`${status}: generatedName=${anyErr.generatedName} schema=${JSON.stringify(anyErr.schema)}\n`);
    }

    const fern = convert({ openApiIr: ir, taskContext });
    out.write("=== FERN TYPES ===\n");
    for (const [file, def] of Object.entries(fern.definitionFiles)) {
        if (def.types != null) {
            for (const name of Object.keys(def.types)) {
                out.write(`${file}: type ${name}\n`);
            }
        }
    }
    if (fern.packageMarkerFile.types != null) {
        for (const name of Object.keys(fern.packageMarkerFile.types)) {
            out.write(`__package__.yml: type ${name}\n`);
        }
    }
    out.write("=== FERN ERRORS ===\n");
    for (const [file, def] of Object.entries(fern.definitionFiles)) {
        if (def.errors != null) {
            for (const [name, decl] of Object.entries(def.errors)) {
                out.write(`${file}: error ${name} => ${JSON.stringify(decl)}\n`);
            }
        }
    }
    if (fern.packageMarkerFile.errors != null) {
        for (const [name, decl] of Object.entries(fern.packageMarkerFile.errors)) {
            out.write(`__package__.yml: error ${name} => ${JSON.stringify(decl)}\n`);
        }
    }
    out.end();
    console.log("done");
}

main().catch((e) => {
    console.error("CRASH", e);
    process.exit(1);
});

