import { AbsoluteFilePath } from "@fern-api/fs-utils";
import { generateIntermediateRepresentation } from "@fern-api/ir-generator";
import { convertIrToFdrApi } from "@fern-api/register";
import { convertAPIDefinitionToDb, convertDbAPIDefinitionToRead, SDKSnippetHolder } from "@fern-api/fdr-sdk";
import { convertOpenApiWorkspaceToFernWorkspace } from "@fern-api/workspace-loader";

async function main() {
    const fs = await import("fs");
    const path = await import("path");
    const specPath = process.argv[2];
    const outDir = process.argv[3] ?? "/tmp/opencode/union-description/fdr-dump";
    fs.mkdirSync(outDir, { recursive: true });
    const logger = { debug: () => {}, info: () => {}, warn: () => {}, error: (x: unknown) => console.error("LOGERR", x), trace: () => {} };
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    const taskContext: any = { logger, failAndThrow: (msg: string) => { throw new Error(msg); } };
    const openapiWorkspace = {
        type: "openapi",
        name: "union",
        namespace: undefined,
        absoluteFilepath: AbsoluteFilePath.of("/DUMMY"),
        absolutePathToOpenAPI: AbsoluteFilePath.of(specPath),
        absolutePathToAsyncAPI: undefined,
        absolutePathToOpenAPIOverrides: undefined,
        generatorsConfiguration: undefined,
        workspaceName: "union"
    };
    const fernWorkspace = await convertOpenApiWorkspaceToFernWorkspace(openapiWorkspace, taskContext);
    const ir = await generateIntermediateRepresentation({ workspace: fernWorkspace, audiences: { type: "all" }, generationLanguage: undefined });
    const fdrApi = convertIrToFdrApi(ir, {});
    const db = convertAPIDefinitionToDb(fdrApi, "", new SDKSnippetHolder({ packageToSdkId: {}, snippetsBySdkId: {}, snippetsConfiguration: {} }));
    const read = convertDbAPIDefinitionToRead(db);
    const name = path.basename(specPath).replace(/\.(yml|yaml|json)$/, "");
    fs.writeFileSync(path.join(outDir, `${name}-fdr.json`), JSON.stringify(fdrApi, null, 2));
    fs.writeFileSync(path.join(outDir, `${name}-read.json`), JSON.stringify(read, null, 2));
    console.log("done");
}
main();

